// This code has been fully generated by an AI.
//
// Activity detail page: track on the map and synchronized charts. Moving the
// cursor over a chart shows the position on the map.

import uPlot from "./vendor/uplot-1.6.32/uPlot.esm.js";
import { coordinates, positionAt, xAxis, chartSeries, thin, rangeIndices, sectionCoordinates, thinnedRange } from "./activity-data.js";
import { bounds } from "./map-style.js";
import { axisStyle, withAlpha } from "./theme-data.js";
import { chartColors, onThemeChange } from "./theme.js";

const status = () => document.getElementById("charts-status");

export async function showActivity(id) {
  let stream;
  try {
    const res = await fetch(`api/activities/${id}/stream`, { headers: { Accept: "application/json" } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    stream = await res.json();
  } catch (err) {
    status().textContent = `Messreihen konnten nicht geladen werden: ${err.message}`;
    status().classList.add("error");
    return;
  }

  const map = await drawMap(stream);
  const position = map?.showPosition ?? null;
  let charts = drawCharts(stream, position);
  let selected = null;
  onThemeChange(() => {
    charts?.destroy();
    charts = drawCharts(stream, position);
    if (selected) charts?.select(...selected);
  });

  // Laps and best efforts carry data-start/data-end (seconds since start):
  // tapping one marks the section in map and charts.
  const rows = [...document.querySelectorAll("[data-start][data-end]")];
  const pick = (el) => {
    const range = rangeIndices(stream.t, Number(el.dataset.start), Number(el.dataset.end));
    if (!range) return;
    rows.forEach((r) => r.classList.toggle("selected", r === el));
    selected = range;
    map?.highlight(sectionCoordinates(stream, ...range));
    charts?.select(...range);
    document.getElementById("map")?.scrollIntoView({ behavior: "smooth", block: "center" });
  };
  for (const el of rows) {
    el.addEventListener("click", () => pick(el));
    el.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        pick(el);
      }
    });
  }
}

async function drawMap(stream) {
  const container = document.getElementById("map");
  const coords = coordinates(stream);
  if (!container || coords.length < 2) return null;

  // Loaded lazily: indoor activities never download MapLibre.
  const { createMap, readMapConfig, maplibregl } = await import("./map.js");
  const map = await createMap(container, readMapConfig(), { bounds: bounds(coords), fitBoundsOptions: { padding: 40 } });

  map.addSource("track", { type: "geojson", data: { type: "Feature", geometry: { type: "LineString", coordinates: coords } } });
  map.addLayer({ id: "track-casing", type: "line", source: "track", layout: { "line-join": "round", "line-cap": "round" },
    paint: { "line-color": "#fff", "line-width": 6, "line-opacity": 0.8 } });
  map.addLayer({ id: "track", type: "line", source: "track", layout: { "line-join": "round", "line-cap": "round" },
    paint: { "line-color": getComputedStyle(container).getPropertyValue("--cat").trim() || "#d9480f", "line-width": 3.5 } });

  map.addSource("section", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
  map.addLayer({ id: "section", type: "line", source: "section", layout: { "line-join": "round", "line-cap": "round" },
    paint: { "line-color": "#1971c2", "line-width": 6 } });

  new maplibregl.Marker({ color: "#2b8a3e", scale: 0.7 }).setLngLat(coords[0]).setPopup(new maplibregl.Popup().setText("Start")).addTo(map);
  new maplibregl.Marker({ color: "#c92a2a", scale: 0.7 }).setLngLat(coords.at(-1)).setPopup(new maplibregl.Popup().setText("Ziel")).addTo(map);

  // Marker that follows the chart cursor; added on first use.
  const el = document.createElement("div");
  el.className = "position-marker";
  const marker = new maplibregl.Marker({ element: el });
  let added = false;
  return {
    showPosition(lngLat) {
      marker.setLngLat(lngLat);
      if (!added) {
        marker.addTo(map);
        added = true;
      }
    },
    highlight(section) {
      if (section.length < 2) return;
      map.getSource("section").setData({ type: "Feature", geometry: { type: "LineString", coordinates: section } });
      map.fitBounds(bounds(section), { padding: 50, maxZoom: 16 });
    },
  };
}

const fmt = (v, digits) => v.toLocaleString("de-DE", { maximumFractionDigits: digits });

/**
 * Draws one compact chart per channel with a shared cursor. Instead of
 * uPlot's legend table every chart shows its value in its header and the
 * card header shows the x position. Returns a handle to redraw on theme
 * changes, or null without data.
 */
function drawCharts(stream, showPosition) {
  const container = document.getElementById("charts");
  const xOut = document.getElementById("charts-x");
  const axis = xAxis(stream);
  const all = chartSeries(stream);
  if (!all.length) {
    status()?.replaceChildren("Keine Messreihen vorhanden.");
    return null;
  }
  const { x, series, index } = thin(axis.values, all);
  status()?.remove();

  const colors = chartColors();
  const width = () => container.clientWidth;
  const plots = [];
  const sync = uPlot.sync("activity");

  for (const s of series) {
    const box = document.createElement("section");
    box.className = "chart";
    const head = document.createElement("header");
    const name = document.createElement("span");
    name.textContent = `${s.label} (${s.unit})`;
    const out = document.createElement("output");
    head.append(name, out);
    box.append(head);
    container.append(box);
    const color = colors.series[s.key] || s.color;
    const last = s === series.at(-1);
    const plot = new uPlot({
      width: width(),
      height: s.key === "alt" ? 140 : 110,
      legend: { show: false },
      cursor: { sync: { key: sync.key }, drag: { x: true, y: false }, points: { size: 7, fill: color } },
      scales: { x: { time: false } },
      axes: [
        axisStyle(colors, { size: last ? 34 : 20, values: (u, ticks) => (last ? ticks.map((v) => fmt(v, 1)) : ticks.map(() => "")) }),
        axisStyle(colors, { size: 44, values: (u, ticks) => ticks.map((v) => fmt(v, 0)) }),
      ],
      series: [
        {},
        { stroke: color, width: 1.5, fill: s.fill ? withAlpha(color, 0.2) : undefined, spanGaps: false, points: { show: false } },
      ],
      hooks: {
        setCursor: [
          (u) => {
            const i = u.cursor.idx;
            const v = i == null ? null : u.data[1][i];
            out.textContent = v == null ? "" : `${fmt(v, 1)} ${s.unit}`;
            if (last) xOut.textContent = i == null ? "" : `${fmt(u.data[0][i], 2)} ${axis.unit}`;
            if (!showPosition || i == null) return;
            const pos = positionAt(stream, index[i]);
            if (pos) showPosition(pos);
          },
        ],
      },
    }, [x, s.values], box);
    plots.push(plot);
  }

  const resize = new ResizeObserver(() => plots.forEach((p) => p.setSize({ width: width(), height: p.height })));
  resize.observe(container);
  return {
    select(first, last) {
      const range = thinnedRange(index, first, last);
      if (!range) return;
      for (const p of plots) {
        const left = p.valToPos(x[range[0]], "x");
        const right = p.valToPos(x[range[1]], "x");
        p.setSelect({ left, width: Math.max(2, right - left), top: 0, height: p.over.clientHeight }, false);
      }
    },
    destroy() {
      resize.disconnect();
      plots.forEach((p) => p.destroy());
      container.replaceChildren();
      xOut.textContent = "";
    },
  };
}
